
LAB_ENGINES.economy={
 init(c,seed){const v=c.variant;return {cash:30,wood:0,food:0,ore:0,tools:0,workers:1,day:1,pos:0,owned:[],seed,prices:[4,6,8],stock:[0,0,0],jobs:0,stations:[],route:[],selected:null,target:v==='market'?120:100,rounds:0};},
 render(d,c){const v=c.variant;const status='<div class="lab-callout">💰 '+d.cash+' coins · Day '+d.day+' · Goal '+d.target+'</div>';
 if(v==='market')return status+'<p>Buy low and sell high. Travelling changes the three market prices. Reach 120 coins in cash and stock value.</p><div class="lab-market">'+['🌾 Grain','🍎 Apples','🥔 Potatoes'].map((x,i)=>'<section><h3>'+x+'</h3><p>Price '+d.prices[i]+' · Owned '+d.stock[i]+'</p>'+labButton('buy','Buy one',i)+labButton('sell','Sell one',i)+'</section>').join('')+'</div>'+labButton('travel','Travel to next market');
 if(v==='property')return status+'<p>Roll, travel and decide whether to buy. Shops earn income when you pass them. Reach 100 coins in cash and property value.</p>'+labGrid(Array.from({length:12},(_,i)=>i),4,i=>(d.pos===i?'🚶 ':'')+(i===0?'🏠 Start':d.owned.includes(i)?'🏪':'🏬')+'<small>'+i+'</small>')+'<p>Current shop: '+(10+d.pos*2)+' coins · Income '+(3+d.pos)+'</p>'+labButton('roll','Roll and travel')+labButton('shop','Buy this shop',0,d.pos===0||d.owned.includes(d.pos));
 if(v==='mine')return status+'<p>Build a continuous railway from the depot (top left) to the mine (bottom right). Trains earn ore; sell it or buy another train.</p>'+labGrid(Array.from({length:16},(_,i)=>i),4,i=>i===0?'🏠':i===15?'⛏':d.route.includes(i)?'🛤':'·')+'<p>Trains '+d.workers+' · Ore '+d.ore+'</p>'+labButton('train','Run trains')+labButton('sellore','Sell ore · 5 coins each')+labButton('hire','Buy train · 20 coins');
 if(v==='clinic')return status+'<p>Treat the waiting pets. Hire staff to treat more patients per day; keep enough coins for supplies.</p><div class="lab-callout">🐶 🐱 🐰 · '+d.workers+' vets · '+d.jobs+' patients helped</div>'+labButton('treat','Treat pets · cost 2, earn 7 per vet')+labButton('hire','Hire vet · 20 coins');
 return status+'<p>'+ (v==='factory'?'Assign workers to a production chain. Two ore makes one tool; sell tools for 12 coins.':'Gather resources, craft tools and grow your island. Each tool needs two wood and one food; sell it for 12 coins.')+'</p><div class="lab-resources"><span>🪵 '+d.wood+' wood</span><span>🍎 '+d.food+' food</span><span>🪨 '+d.ore+' ore</span><span>🔧 '+d.tools+' tools</span><span>👷 '+d.workers+' workers</span></div>'+ (v==='factory'?labButton('ore','Mine ore'):labButton('wood','Gather wood')+labButton('food','Harvest food'))+labButton('craft','Craft tools')+labButton('selltools','Sell tools')+labButton('hire','Hire worker · 20 coins');
 },
 action(d,a,n,c){const v=c.variant;let moved=false;if(a==='hire'){if(d.cash<20){labMiss('Save 20 coins first.');return;}d.cash-=20;d.workers++;moved=true;}
 if(v==='market'){if(a==='buy'){if(d.cash<d.prices[n]){labMiss('Not enough cash for that purchase.');return;}d.cash-=d.prices[n];d.stock[n]++;moved=true;}if(a==='sell'&&d.stock[n]){d.stock[n]--;d.cash+=d.prices[n];moved=true;}if(a==='travel'){d.prices=d.prices.map((_,i)=>2+(d.day*3+i*5+d.seed)%11);d.day++;moved=true;}}
 if(v==='property'){if(a==='roll'){const roll=1+Math.floor(labRand(d.seed++*7919)()*6);for(let i=0;i<roll;i++){d.pos=(d.pos+1)%12;if(d.pos===0)d.cash+=10;if(d.owned.includes(d.pos))d.cash+=3+d.pos;}game.session.message='Rolled '+roll+'.';d.day++;moved=true;}if(a==='shop'&&d.pos&&!d.owned.includes(d.pos)){const price=10+d.pos*2;if(d.cash<price){labMiss('Save enough coins to buy this shop.');return;}d.cash-=price;d.owned.push(d.pos);moved=true;}}
 if(v==='mine'){if(a==='cell'){const last=d.route.at(-1)??0;if(n===d.route.at(-2)||n===0&&d.route.length===1){d.route.pop();return;}if(!d.route.includes(n)&&labAdjacent(last,n,4))d.route.push(n);return;}if(a==='train'){if(d.route.at(-1)!==15){labMiss('Finish the railway to the mine first.');return;}d.ore+=d.workers;d.day++;moved=true;}if(a==='sellore'){d.cash+=d.ore*5;d.ore=0;moved=true;}}
 if(v==='clinic'&&a==='treat'){if(d.cash<d.workers*2){labMiss('Not enough money for supplies.');return;}d.cash+=d.workers*5;d.jobs+=d.workers;d.day++;moved=true;}
 if(['factory','island'].includes(v)){if(['wood','food','ore'].includes(a)){d[a]+=d.workers;d.day++;moved=true;}if(a==='craft'){const qty=v==='factory'?Math.floor(d.ore/2):Math.min(Math.floor(d.wood/2),d.food);if(!qty){labMiss('Gather the recipe ingredients first.');return;}if(v==='factory')d.ore-=qty*2;else{d.wood-=qty*2;d.food-=qty;}d.tools+=qty;d.day++;moved=true;}if(a==='selltools'){d.cash+=d.tools*12;d.tools=0;moved=true;}}
 if(moved)game.session.moves++;const worth=d.cash+(v==='market'?d.stock.reduce((s,x,i)=>s+x*d.prices[i],0):v==='property'?d.owned.reduce((s,i)=>s+10+i*2,0):0);if(worth>=d.target)labWin('Your plan grew the economy to '+worth+' coins!');
 }
};
